package ru.truetv.probe;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.database.Cursor;
import android.os.*;
import android.provider.*;
import java.io.*;
import java.util.*;

/** Disposable external client. Deliberately has no storage permission. */
public final class FileClient extends Activity {
 public static final String RESULT="ru.truetv.probe.FILE_RESULT";
 protected void onCreate(Bundle state){super.onCreate(state);if(getIntent().getBooleanExtra("verify",false)){Intent report=new Intent(RESULT).setPackage("ru.truetv.launcher");try{Uri uri=Uri.parse(getPreferences(0).getString("uri",""));report.putExtra("text",read(this,uri));report.putExtra("ok",true);}catch(Exception e){report.putExtra("error",e.toString());}sendBroadcast(report);finish();return;}if(state!=null)return;Intent choose=new Intent(getIntent().getStringExtra("action"));String mime=getIntent().getStringExtra("mime");if(mime!=null)choose.setType(mime);if(!Intent.ACTION_OPEN_DOCUMENT_TREE.equals(choose.getAction()))choose.addCategory(Intent.CATEGORY_OPENABLE);choose.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,getIntent().getBooleanExtra("multiple",false));String uri=getIntent().getStringExtra("initial");if(uri!=null)choose.putExtra(DocumentsContract.EXTRA_INITIAL_URI,Uri.parse(uri));choose.putExtra(Intent.EXTRA_TITLE,"created.txt");try{startActivityForResult(choose,10);}catch(Exception e){sendBroadcast(new Intent(RESULT).setPackage("ru.truetv.launcher").putExtra("error",e.toString()));finish();}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);Intent report=new Intent(RESULT).setPackage("ru.truetv.launcher");try{if(result!=RESULT_OK||data==null)throw new IOException("Picker cancelled");Uri uri=data.getData();report.putExtra("uri",uri.toString());report.putExtra("flags",data.getFlags());boolean persist=(data.getFlags()&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)!=0;if(persist){getContentResolver().takePersistableUriPermission(uri,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));getPreferences(0).edit().putString("uri",uri.toString()).commit();}report.putExtra("persist",persist);boolean tree=DocumentsContract.isTreeUri(uri);report.putExtra("tree",tree);if(tree){Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(uri,DocumentsContract.getTreeDocumentId(uri));int count=0;String text="";try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_MIME_TYPE},null,null,null)){while(c.moveToNext()){count++;if(!DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(1)))text+=read(this,DocumentsContract.buildDocumentUriUsingTree(uri,c.getString(0)));}}report.putExtra("count",count);report.putExtra("text",text);String outside=getIntent().getStringExtra("outside");if(outside!=null){boolean denied=false;try{read(this,Uri.parse(outside));}catch(SecurityException|FileNotFoundException expected){denied=true;}report.putExtra("outsideDenied",denied);}}else{if(Intent.ACTION_CREATE_DOCUMENT.equals(getIntent().getStringExtra("action")))try(OutputStream out=getContentResolver().openOutputStream(uri,"w")){out.write("created-by-client".getBytes("UTF-8"));}int count=data.getClipData()==null?1:data.getClipData().getItemCount();String text="";for(int i=0;i<count;i++)text+=read(this,data.getClipData()==null?uri:data.getClipData().getItemAt(i).getUri());report.putExtra("text",text);report.putExtra("count",count);try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c.moveToFirst())report.putExtra("name",c.getString(0));}try(ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(uri,"r");FileInputStream in=new FileInputStream(fd.getFileDescriptor())){in.getChannel().position(1);report.putExtra("seek",in.read()>=0);}}
 report.putExtra("ok",true);}catch(Exception e){report.putExtra("error",e.toString());}sendBroadcast(report);finish();}
 static String read(Context c,Uri uri)throws Exception {try(InputStream in=c.getContentResolver().openInputStream(uri);ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] buffer=new byte[1024];int n;while((n=in.read(buffer))!=-1){if(bytes.size()>100000)throw new IOException("Probe fixture too large");bytes.write(buffer,0,n);}return new String(bytes.toByteArray(),"UTF-8");}}
}
